					answerType(map[string]string{"a-hosted": "hosted", "b-proxy": "proxy", "sub-group": "group"}[name])(w, r, name)
				})

			members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)

			if err != nil {
				t.Fatalf("err = %v", err)
